Here is the commit message:
ACPI / video: Revert "thinkpad_acpi: Use
 acpi_video_handles_brightness_key_presses()"

acpi_video_handles_brightness_key_presses()'s may return false if the i915
driver is not loaded yet when thinkpad_acpi loads, and then return true
after the i915 driver has loaded. This means that thinkpad_acpi cannot
use it as is since thinkpad_acpi caches the return value.

This reverts commit 7714687a2b2d ("thinkpad_acpi: Use
acpi_video_handles_brightness_key_presses()").

Fixes: 7714687a2b2d "thinkpad_acpi: Use acpi_video_handles_brightness_key_presses()"
Signed-off-by: Hans de Goede <hdegoede@redhat.com>
Acked-by: Darren Hart <dvhart@linux.intel.com>
Acked-by: Henrique de Moraes Holschuh <hmh@hmh.eng.br>
Signed-off-by: Rafael J. Wysocki <rafael.j.wysocki@intel.com>

Here is the root cause:
The bug arises from the use of the function `acpi_video_handles_brightness_key_presses()`, which can return false if the i915 driver is not loaded when the `thinkpad_acpi` module initializes. This leads to a situation where `thinkpad_acpi` caches the return value, resulting in incorrect behavior when the i915 driver is subsequently loaded and the function's return value changes to true. This inconsistency causes issues with brightness key press handling on ThinkPad devices.

Here is the patch:

 static int __init hotkey_init(struct ibm_init_struct *iibm)
 {
 	/* Requirements for changing the default keymaps:
 	 *
 	 * 1. Many of the keys are mapped to KEY_RESERVED for very
 	 *    good reasons.  Do not change them unless you have deep
 	 *    knowledge on the IBM and Lenovo ThinkPad firmware for
 	 *    the various ThinkPad models.  The driver behaves
 	 *    differently for KEY_RESERVED: such keys have their
 	 *    hot key mask *unset* in mask_recommended, and also
 	 *    in the initial hot key mask programmed into the
 	 *    firmware at driver load time, which means the firm-
 	 *    ware may react very differently if you change them to
 	 *    something else;
 	 *
 	 * 2. You must be subscribed to the linux-thinkpad and
 	 *    ibm-acpi-devel mailing lists, and you should read the
 	 *    list archives since 2007 if you want to change the
 	 *    keymaps.  This requirement exists so that you will
 	 *    know the past history of problems with the thinkpad-
 	 *    acpi driver keymaps, and also that you will be
 	 *    listening to any bug reports;
 	 *
 	 * 3. Do not send thinkpad-acpi specific patches directly to
 	 *    for merging, *ever*.  Send them to the linux-acpi
 	 *    mailinglist for comments.  Merging is to be done only
 	 *    through acpi-test and the ACPI maintainer.
 	 *
 	 * If the above is too much to ask, don't change the keymap.
 	 * Ask the thinkpad-acpi maintainer to do it, instead.
 	 */

 	enum keymap_index {
 		TPACPI_KEYMAP_IBM_GENERIC = 0,
 		TPACPI_KEYMAP_LENOVO_GENERIC,
 	};

 	static const tpacpi_keymap_t tpacpi_keymaps[] __initconst = {
 	/* Generic keymap for IBM ThinkPads */
 	[TPACPI_KEYMAP_IBM_GENERIC] = {
 		/* Scan Codes 0x00 to 0x0B: ACPI HKEY FN+F1..F12 */
 		KEY_FN_F1,	KEY_BATTERY,	KEY_COFFEE,	KEY_SLEEP,
 		KEY_WLAN,	KEY_FN_F6, KEY_SWITCHVIDEOMODE, KEY_FN_F8,
 		KEY_FN_F9,	KEY_FN_F10,	KEY_FN_F11,	KEY_SUSPEND,

 		/* Scan codes 0x0C to 0x1F: Other ACPI HKEY hot keys */
 		KEY_UNKNOWN,	/* 0x0C: FN+BACKSPACE */
 		KEY_UNKNOWN,	/* 0x0D: FN+INSERT */
 		KEY_UNKNOWN,	/* 0x0E: FN+DELETE */

 		/* brightness: firmware always reacts to them */
 		KEY_RESERVED,	/* 0x0F: FN+HOME (brightness up) */
 		KEY_RESERVED,	/* 0x10: FN+END (brightness down) */

 		/* Thinklight: firmware always react to it */
 		KEY_RESERVED,	/* 0x11: FN+PGUP (thinklight toggle) */

 		KEY_UNKNOWN,	/* 0x12: FN+PGDOWN */
 		KEY_ZOOM,	/* 0x13: FN+SPACE (zoom) */

 		/* Volume: firmware always react to it and reprograms
 		 * the built-in *extra* mixer.  Never map it to control
 		 * another mixer by default. */
 		KEY_RESERVED,	/* 0x14: VOLUME UP */
 		KEY_RESERVED,	/* 0x15: VOLUME DOWN */
 		KEY_RESERVED,	/* 0x16: MUTE */

 		KEY_VENDOR,	/* 0x17: Thinkpad/AccessIBM/Lenovo */

 		/* (assignments unknown, please report if found) */
 		KEY_UNKNOWN, KEY_UNKNOWN, KEY_UNKNOWN, KEY_UNKNOWN,
 		KEY_UNKNOWN, KEY_UNKNOWN, KEY_UNKNOWN, KEY_UNKNOWN,

 		/* No assignments, only used for Adaptive keyboards. */
 		KEY_UNKNOWN, KEY_UNKNOWN, KEY_UNKNOWN, KEY_UNKNOWN,
 		KEY_UNKNOWN, KEY_UNKNOWN, KEY_UNKNOWN, KEY_UNKNOWN,
 		KEY_UNKNOWN, KEY_UNKNOWN, KEY_UNKNOWN, KEY_UNKNOWN,
 		KEY_UNKNOWN, KEY_UNKNOWN, KEY_UNKNOWN, KEY_UNKNOWN,
 		KEY_UNKNOWN, KEY_UNKNOWN, KEY_UNKNOWN,
 		},

 	/* Generic keymap for Lenovo ThinkPads */
 	[TPACPI_KEYMAP_LENOVO_GENERIC] = {
 		/* Scan Codes 0x00 to 0x0B: ACPI HKEY FN+F1..F12 */
 		KEY_FN_F1,	KEY_COFFEE,	KEY_BATTERY,	KEY_SLEEP,
 		KEY_WLAN,	KEY_CAMERA, KEY_SWITCHVIDEOMODE, KEY_FN_F8,
 		KEY_FN_F9,	KEY_FN_F10,	KEY_FN_F11,	KEY_SUSPEND,

 		/* Scan codes 0x0C to 0x1F: Other ACPI HKEY hot keys */
 		KEY_UNKNOWN,	/* 0x0C: FN+BACKSPACE */
 		KEY_UNKNOWN,	/* 0x0D: FN+INSERT */
 		KEY_UNKNOWN,	/* 0x0E: FN+DELETE */

 		/* These should be enabled --only-- when ACPI video
 		 * is disabled (i.e. in "vendor" mode), and are handled
 		 * in a special way by the init code */
 		KEY_BRIGHTNESSUP,	/* 0x0F: FN+HOME (brightness up) */
 		KEY_BRIGHTNESSDOWN,	/* 0x10: FN+END (brightness down) */

 		KEY_RESERVED,	/* 0x11: FN+PGUP (thinklight toggle) */

 		KEY_UNKNOWN,	/* 0x12: FN+PGDOWN */
 		KEY_ZOOM,	/* 0x13: FN+SPACE (zoom) */

 		/* Volume: z60/z61, T60 (BIOS version?): firmware always
 		 * react to it and reprograms the built-in *extra* mixer.
 		 * Never map it to control another mixer by default.
 		 *
 		 * T60?, T61, R60?, R61: firmware and EC tries to send
 		 * these over the regular keyboard, so these are no-ops,
 		 * but there are still weird bugs re. MUTE, so do not
 		 * change unless you get test reports from all Lenovo
 		 * models.  May cause the BIOS to interfere with the
 		 * HDA mixer.
 		 */
 		KEY_RESERVED,	/* 0x14: VOLUME UP */
 		KEY_RESERVED,	/* 0x15: VOLUME DOWN */
 		KEY_RESERVED,	/* 0x16: MUTE */

 		KEY_VENDOR,	/* 0x17: Thinkpad/AccessIBM/Lenovo */

 		/* (assignments unknown, please report if found) */
 		KEY_UNKNOWN, KEY_UNKNOWN,

 		/*
 		 * The mic mute button only sends 0x1a.  It does not
 		 * automatically mute the mic or change the mute light.
 		 */
 		KEY_MICMUTE,	/* 0x1a: Mic mute (since ?400 or so) */

 		/* (assignments unknown, please report if found) */
 		KEY_UNKNOWN,

 		/* Extra keys in use since the X240 / T440 / T540 */
 		KEY_CONFIG, KEY_SEARCH, KEY_SCALE, KEY_FILE,

 		/*
 		 * These are the adaptive keyboard keycodes for Carbon X1 2014.
 		 * The first item in this list is the Mute button which is
 		 * emitted with 0x103 through
 		 * adaptive_keyboard_hotkey_notify_hotkey() when the sound
 		 * symbol is held.
 		 * We'll need to offset those by 0x20.
 		 */
 		KEY_RESERVED,        /* Mute held, 0x103 */
 		KEY_BRIGHTNESS_MIN,  /* Backlight off */
 		KEY_RESERVED,        /* Clipping tool */
 		KEY_RESERVED,        /* Cloud */
 		KEY_RESERVED,
 		KEY_VOICECOMMAND,    /* Voice */
 		KEY_RESERVED,
 		KEY_RESERVED,        /* Gestures */
 		KEY_RESERVED,
 		KEY_RESERVED,
 		KEY_RESERVED,
 		KEY_CONFIG,          /* Settings */
 		KEY_RESERVED,        /* New tab */
 		KEY_REFRESH,         /* Reload */
 		KEY_BACK,            /* Back */
 		KEY_RESERVED,        /* Microphone down */
 		KEY_RESERVED,        /* Microphone up */
 		KEY_RESERVED,        /* Microphone cancellation */
 		KEY_RESERVED,        /* Camera mode */
 		KEY_RESERVED,        /* Rotate display, 0x116 */
 		},
 	};

 	static const struct tpacpi_quirk tpacpi_keymap_qtable[] __initconst = {
 		/* Generic maps (fallback) */
 		{
 		  .vendor = PCI_VENDOR_ID_IBM,
 		  .bios = TPACPI_MATCH_ANY, .ec = TPACPI_MATCH_ANY,
 		  .quirks = TPACPI_KEYMAP_IBM_GENERIC,
 		},
 		{
 		  .vendor = PCI_VENDOR_ID_LENOVO,
 		  .bios = TPACPI_MATCH_ANY, .ec = TPACPI_MATCH_ANY,
 		  .quirks = TPACPI_KEYMAP_LENOVO_GENERIC,
 		},
 	};

 #define TPACPI_HOTKEY_MAP_SIZE		sizeof(tpacpi_keymap_t)
 #define TPACPI_HOTKEY_MAP_TYPESIZE	sizeof(tpacpi_keymap_entry_t)

 	int res, i;
 	int status;
 	int hkeyv;
 	bool radiosw_state  = false;
 	bool tabletsw_state = false;

 	unsigned long quirks;
 	unsigned long keymap_id;

 	vdbg_printk(TPACPI_DBG_INIT | TPACPI_DBG_HKEY,
 			"initializing hotkey subdriver\n");

 	BUG_ON(!tpacpi_inputdev);
 	BUG_ON(tpacpi_inputdev->open != NULL ||
 	       tpacpi_inputdev->close != NULL);

 	TPACPI_ACPIHANDLE_INIT(hkey);
 	mutex_init(&hotkey_mutex);

 #ifdef CONFIG_THINKPAD_ACPI_HOTKEY_POLL
 	mutex_init(&hotkey_thread_data_mutex);
 #endif

 	/* hotkey not supported on 570 */
 	tp_features.hotkey = hkey_handle != NULL;

 	vdbg_printk(TPACPI_DBG_INIT | TPACPI_DBG_HKEY,
 		"hotkeys are %s\n",
 		str_supported(tp_features.hotkey));

 	if (!tp_features.hotkey)
 		return 1;

 	/*
 	 * Check if we have an adaptive keyboard, like on the
 	 * Lenovo Carbon X1 2014 (2nd Gen).
 	 */
 	if (acpi_evalf(hkey_handle, &hkeyv, "MHKV", "qd")) {
 		if ((hkeyv >> 8) == 2) {
 			tp_features.has_adaptive_kbd = true;
 			res = sysfs_create_group(&tpacpi_pdev->dev.kobj,
 					&adaptive_kbd_attr_group);
 			if (res)
 				goto err_exit;
 		}
 	}

 	quirks = tpacpi_check_quirks(tpacpi_hotkey_qtable,
 				     ARRAY_SIZE(tpacpi_hotkey_qtable));

 	tpacpi_disable_brightness_delay();

 	/* MUST have enough space for all attributes to be added to
 	 * hotkey_dev_attributes */
 	hotkey_dev_attributes = create_attr_set(
 					ARRAY_SIZE(hotkey_attributes) + 2,
 					NULL);
 	if (!hotkey_dev_attributes)
 		return -ENOMEM;
 	res = add_many_to_attr_set(hotkey_dev_attributes,
 			hotkey_attributes,
 			ARRAY_SIZE(hotkey_attributes));
 	if (res)
 		goto err_exit;

 	/* mask not supported on 600e/x, 770e, 770x, A21e, A2xm/p,
 	   A30, R30, R31, T20-22, X20-21, X22-24.  Detected by checking
 	   for HKEY interface version 0x100 */
 	if (acpi_evalf(hkey_handle, &hkeyv, "MHKV", "qd")) {
 		if ((hkeyv >> 8) != 1) {
 			pr_err("unknown version of the HKEY interface: 0x%x\n",
 			       hkeyv);
 			pr_err("please report this to %s\n", TPACPI_MAIL);
 		} else {
 			/*
 			 * MHKV 0x100 in A31, R40, R40e,
 			 * T4x, X31, and later
 			 */
 			vdbg_printk(TPACPI_DBG_INIT | TPACPI_DBG_HKEY,
 				"firmware HKEY interface version: 0x%x\n",
 				hkeyv);

 			/* Paranoia check AND init hotkey_all_mask */
 			if (!acpi_evalf(hkey_handle, &hotkey_all_mask,
 					"MHKA", "qd")) {
 				pr_err("missing MHKA handler, "
 				       "please report this to %s\n",
 				       TPACPI_MAIL);
 				/* Fallback: pre-init for FN+F3,F4,F12 */
 				hotkey_all_mask = 0x080cU;
 			} else {
 				tp_features.hotkey_mask = 1;
 			}
 		}
 	}

 	vdbg_printk(TPACPI_DBG_INIT | TPACPI_DBG_HKEY,
 		"hotkey masks are %s\n",
 		str_supported(tp_features.hotkey_mask));

 	/* Init hotkey_all_mask if not initialized yet */
 	if (!tp_features.hotkey_mask && !hotkey_all_mask &&
 	    (quirks & TPACPI_HK_Q_INIMASK))
 		hotkey_all_mask = 0x080cU;  /* FN+F12, FN+F4, FN+F3 */

 	/* Init hotkey_acpi_mask and hotkey_orig_mask */
 	if (tp_features.hotkey_mask) {
 		/* hotkey_source_mask *must* be zero for
 		 * the first hotkey_mask_get to return hotkey_orig_mask */
 		res = hotkey_mask_get();
 		if (res)
 			goto err_exit;

 		hotkey_orig_mask = hotkey_acpi_mask;
 	} else {
 		hotkey_orig_mask = hotkey_all_mask;
 		hotkey_acpi_mask = hotkey_all_mask;
 	}

 #ifdef CONFIG_THINKPAD_ACPI_DEBUGFACILITIES
 	if (dbg_wlswemul) {
 		tp_features.hotkey_wlsw = 1;
 		radiosw_state = !!tpacpi_wlsw_emulstate;
 		pr_info("radio switch emulation enabled\n");
 	} else
 #endif
 	/* Not all thinkpads have a hardware radio switch */
 	if (acpi_evalf(hkey_handle, &status, "WLSW", "qd")) {
 		tp_features.hotkey_wlsw = 1;
 		radiosw_state = !!status;
 		pr_info("radio switch found; radios are %s\n",
 			enabled(status, 0));
 	}
 	if (tp_features.hotkey_wlsw)
 		res = add_to_attr_set(hotkey_dev_attributes,
 				&dev_attr_hotkey_radio_sw.attr);

 	/* For X41t, X60t, X61t Tablets... */
 	if (!res && acpi_evalf(hkey_handle, &status, "MHKG", "qd")) {
 		tp_features.hotkey_tablet = 1;
 		tabletsw_state = !!(status & TP_HOTKEY_TABLET_MASK);
 		pr_info("possible tablet mode switch found; "
 			"ThinkPad in %s mode\n",
 			(tabletsw_state) ? "tablet" : "laptop");
 		res = add_to_attr_set(hotkey_dev_attributes,
 				&dev_attr_hotkey_tablet_mode.attr);
 	}

 	if (!res)
 		res = register_attr_set_with_sysfs(
 				hotkey_dev_attributes,
 				&tpacpi_pdev->dev.kobj);
 	if (res)
 		goto err_exit;

 	/* Set up key map */
 	hotkey_keycode_map = kmalloc(TPACPI_HOTKEY_MAP_SIZE,
 					GFP_KERNEL);
 	if (!hotkey_keycode_map) {
 		pr_err("failed to allocate memory for key map\n");
 		res = -ENOMEM;
 		goto err_exit;
 	}

 	keymap_id = tpacpi_check_quirks(tpacpi_keymap_qtable,
 					ARRAY_SIZE(tpacpi_keymap_qtable));
 	BUG_ON(keymap_id >= ARRAY_SIZE(tpacpi_keymaps));
 	dbg_printk(TPACPI_DBG_INIT | TPACPI_DBG_HKEY,
 		   "using keymap number %lu\n", keymap_id);

 	memcpy(hotkey_keycode_map, &tpacpi_keymaps[keymap_id],
 		TPACPI_HOTKEY_MAP_SIZE);

 	input_set_capability(tpacpi_inputdev, EV_MSC, MSC_SCAN);
 	tpacpi_inputdev->keycodesize = TPACPI_HOTKEY_MAP_TYPESIZE;
 	tpacpi_inputdev->keycodemax = TPACPI_HOTKEY_MAP_LEN;
 	tpacpi_inputdev->keycode = hotkey_keycode_map;
 	for (i = 0; i < TPACPI_HOTKEY_MAP_LEN; i++) {
 		if (hotkey_keycode_map[i] != KEY_RESERVED) {
 			input_set_capability(tpacpi_inputdev, EV_KEY,
 						hotkey_keycode_map[i]);
 		} else {
 			if (i < sizeof(hotkey_reserved_mask)*8)
 				hotkey_reserved_mask |= 1 << i;
 		}
 	}

 	if (tp_features.hotkey_wlsw) {
 		input_set_capability(tpacpi_inputdev, EV_SW, SW_RFKILL_ALL);
 		input_report_switch(tpacpi_inputdev,
 				    SW_RFKILL_ALL, radiosw_state);
 	}
 	if (tp_features.hotkey_tablet) {
 		input_set_capability(tpacpi_inputdev, EV_SW, SW_TABLET_MODE);
 		input_report_switch(tpacpi_inputdev,
 				    SW_TABLET_MODE, tabletsw_state);
 	}

 	/* Do not issue duplicate brightness change events to
 	 * userspace. tpacpi_detect_brightness_capabilities() must have
 	 * been called before this point  */
-	if (acpi_video_handles_brightness_key_presses()) {
+	if (acpi_video_get_backlight_type() != acpi_backlight_vendor) {
 		pr_info("This ThinkPad has standard ACPI backlight "
 			"brightness control, supported by the ACPI "
 			"video driver\n");
 		pr_notice("Disabling thinkpad-acpi brightness events "
 			  "by default...\n");

 		/* Disable brightness up/down on Lenovo thinkpads when
 		 * ACPI is handling them, otherwise it is plain impossible
 		 * for userspace to do something even remotely sane */
 		hotkey_reserved_mask |=
 			(1 << TP_ACPI_HOTKEYSCAN_FNHOME)
 			| (1 << TP_ACPI_HOTKEYSCAN_FNEND);
 		hotkey_unmap(TP_ACPI_HOTKEYSCAN_FNHOME);
 		hotkey_unmap(TP_ACPI_HOTKEYSCAN_FNEND);
 	}

 #ifdef CONFIG_THINKPAD_ACPI_HOTKEY_POLL
 	hotkey_source_mask = TPACPI_HKEY_NVRAM_GOOD_MASK
 				& ~hotkey_all_mask
 				& ~hotkey_reserved_mask;

 	vdbg_printk(TPACPI_DBG_INIT | TPACPI_DBG_HKEY,
 		    "hotkey source mask 0x%08x, polling freq %u\n",
 		    hotkey_source_mask, hotkey_poll_freq);
 #endif

 	dbg_printk(TPACPI_DBG_INIT | TPACPI_DBG_HKEY,
 			"enabling firmware HKEY event interface...\n");
 	res = hotkey_status_set(true);
 	if (res) {
 		hotkey_exit();
 		return res;
 	}
 	res = hotkey_mask_set(((hotkey_all_mask & ~hotkey_reserved_mask)
 			       | hotkey_driver_mask)
 			      & ~hotkey_source_mask);
 	if (res < 0 && res != -ENXIO) {
 		hotkey_exit();
 		return res;
 	}
 	hotkey_user_mask = (hotkey_acpi_mask | hotkey_source_mask)
 				& ~hotkey_reserved_mask;
 	vdbg_printk(TPACPI_DBG_INIT | TPACPI_DBG_HKEY,
 		"initial masks: user=0x%08x, fw=0x%08x, poll=0x%08x\n",
 		hotkey_user_mask, hotkey_acpi_mask, hotkey_source_mask);

 	tpacpi_inputdev->open = &hotkey_inputdev_open;
 	tpacpi_inputdev->close = &hotkey_inputdev_close;

 	hotkey_poll_setup_safe(true);

 	return 0;

 err_exit:
 	delete_attr_set(hotkey_dev_attributes, &tpacpi_pdev->dev.kobj);
 	sysfs_remove_group(&tpacpi_pdev->dev.kobj,
 			&adaptive_kbd_attr_group);

 	hotkey_dev_attributes = NULL;

 	return (res < 0) ? res : 1;
 }



